'use strict';

// MAIN //

/**
* Returns a function which should only be invoked at most once per a specified interval.
*
* @private
* @param {Function} fcn - function to wrap
* @param {NonNegativeInteger} interval - number of milliseconds before a function can be invoked again
* @returns {Function} wrapped function
*/
function throttle( fcn, interval ) { // TODO: make more robust and comprehensive and move to `@stdlib/function/throttle`
	var args;
	var flg;

	flg = false;
	return throttled;

	/**
	* Returns a throttled function.
	*
	* @private
	* @param {...*} [args] - arguments
	* @returns {void}
	*/
	function throttled() {
		var i;

		// Cache the latest list of arguments...
		args = [];
		for ( i = 0; i < arguments.length; i++ ) {
			args.push( arguments[ i ] );
		}
		// If the flag is already set, then we're paused...
		if ( flg ) {
			// Nothing left to do, but wait...
			return;
		}
		flg = true;

		// Start the timer for when we can invoke the throttled function:
		setTimeout( onTimeout, interval );
	}

	/**
	* Callback invoked after a delay.
	*
	* @private
	*/
	function onTimeout() {
		fcn.apply( null, args );

		// Now that the function was invoked, we can reset the flag:
		flg = false;
	}
}


// EXPORTS //

module.exports = throttle;
